112	var (
113		betterleaksDetector     *detect.Detector
114		betterleaksDetectorOnce sync.Once
115	)
116	
117	func getDetector() *detect.Detector {
118		betterleaksDetectorOnce.Do(func() {
119			d, err := detect.NewDetectorDefaultConfig()
120			if err != nil {
121				return
122			}
123			betterleaksDetector = d
124		})
125		return betterleaksDetector
126	}
