128	// region represents a byte range to redact.
129	type region struct{ start, end int }
130	
131	// taggedRegion extends region with a label for typed replacement tokens.
132	// Empty label = secret (produces "REDACTED"). Non-empty = PII (produces "[REDACTED_<LABEL>]").
133	type taggedRegion struct {
134		region
135	
136		label string
137	}
138	
139	type jsonReplacement struct {
140		key      string
141		original string
142		redacted string
143	}
144	
145	type connectionStringRule struct {
146		pattern   *regexp.Regexp
147		hasSecret func(string) bool
148	}
149	
150	var connectionStringRules = []connectionStringRule{
151		{pattern: jdbcPattern, hasSecret: hasJDBCPassword},
152		{pattern: databaseURLPattern, hasSecret: hasDatabaseURLSecret},
153		{pattern: keywordDSNPattern, hasSecret: hasKeywordDSNPassword},
154		{pattern: semicolonConnPattern, hasSecret: hasSemicolonConnectionPassword},
155	}
156	
157	// String replaces secrets and PII in s using layered detection:
158	// 1. Entropy-based: high-entropy alphanumeric sequences (threshold 4.5)
159	// 2. Pattern-based: betterleaks regex rules (260+ known secret formats)
160	// 3. Credentialed URIs: URLs containing userinfo passwords
161	// 4. Database connection strings: JDBC, keyword DSNs, and semicolon strings
162	// 5. User-defined custom rules: configured via ConfigureCustomRules
163	// 6. Bounded credential key/value pairs: DB_PASSWORD=...
164	// 7. PII detection: email, phone, address patterns (only when configured via ConfigurePII)
165	// A string is redacted if ANY method flags it.
166	func String(s string) string {
167		var regions []taggedRegion
168	
169		// 1. Entropy-based detection (secrets — always on).
170		for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
171			start, end := loc[0], loc[1]
172	
173			// Don't consume characters that are part of JSON/string escape sequences.
174			// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
175			// (consuming the 'n' from '\n'), and after replacement the '\' would be
176			// followed by 'R' from "REDACTED", creating invalid escape '\R'.
177			// Only skip for known JSON escape letters to avoid trimming real secrets
178			// that happen to follow a literal backslash in decoded content.
179			if start > 0 && s[start-1] == '\\' {
180				switch s[start] {
181				case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
182					start++
183					if end-start < 10 {
184						continue
185					}
186				}
187			}
188	
189			if shannonEntropy(s[start:end]) > entropyThreshold {
190				regions = append(regions, taggedRegion{region: region{start, end}})
191			}
192		}
193	
194		// 2. Pattern-based detection via betterleaks (secrets — always on).
195		if d := getDetector(); d != nil {
196			for _, f := range d.DetectString(s) {
197				if f.Secret == "" {
198					continue
199				}
200				searchFrom := 0
201				for {
202					idx := strings.Index(s[searchFrom:], f.Secret)
203					if idx < 0 {
204						break
205					}
206					absIdx := searchFrom + idx
207					regions = append(regions, taggedRegion{region: region{absIdx, absIdx + len(f.Secret)}})
208					searchFrom = absIdx + len(f.Secret)
209				}
210			}
211		}
212	
213		// 3. Credentialed URIs (secrets — always on).
214		for _, loc := range credentialedURIPattern.FindAllStringIndex(s, -1) {
215			regions = append(regions, taggedRegion{region: region{loc[0], loc[1]}})
216		}
217	
218		// 4. Database and connection-string detection (secrets — always on).
219		regions = append(regions, detectConnectionStrings(s)...)
220	
221		// 5. User-defined custom rules (secrets — only runs when configured).
222		regions = append(regions, detectCustomRules(getCustomRulesConfig(), s)...)
223	
224		// 6. Bounded credential key/value detection (secrets — always on).
225		regions = append(regions, detectCredentialValues(s)...)
226	
227		// 7. PII detection (opt-in — only runs when configured).
228		regions = append(regions, detectPII(getPIIConfig(), s)...)
229	
230		if len(regions) == 0 {
231			return s
232		}
233	
234		// Merge overlapping regions and build result.
235		sort.Slice(regions, func(i, j int) bool {
236			if regions[i].start != regions[j].start {
237				return regions[i].start < regions[j].start
238			}
239			if regions[i].end != regions[j].end {
240				return regions[i].end > regions[j].end // larger region first
241			}
242			return regions[i].label < regions[j].label // deterministic tie-break
243		})
244		merged := []taggedRegion{regions[0]}
245		for _, r := range regions[1:] {
246			last := &merged[len(merged)-1]
247			if r.start <= last.end {
248				if r.end > last.end {
249					last.end = r.end
250				}
251				// Keep the existing label (first/larger region wins)
252			} else {
253				merged = append(merged, r)
254			}
255		}
256	
257		var b strings.Builder
258		prev := 0
259		for _, r := range merged {
260			b.WriteString(s[prev:r.start])
261			b.WriteString(replacementToken(r.label))
262			prev = r.end
263		}
264		b.WriteString(s[prev:])
265		return b.String()
266	}
267	
268	func detectConnectionStrings(s string) []taggedRegion {
269		if !strings.ContainsRune(s, '=') {
270			return nil
271		}
272		var regions []taggedRegion
273		for _, rule := range connectionStringRules {
274			regions = append(regions, detectConnectionStringRule(s, rule)...)
275		}
276		return regions
277	}
278	
279	func detectConnectionStringRule(s string, rule connectionStringRule) []taggedRegion {
280		var regions []taggedRegion
281		for _, loc := range rule.pattern.FindAllStringIndex(s, -1) {
282			start, end := loc[0], trimConnectionStringEnd(s, loc[0], loc[1])
283			if start >= end {
284				continue
285			}
286			if rule.hasSecret(s[start:end]) {
287				regions = append(regions, taggedRegion{region: region{start, end}})
288			}
289		}
290		return regions
291	}
292	
293	func trimConnectionStringEnd(s string, start, end int) int {
294		for end > start {
295			switch s[end-1] {
296			case '.', ',', ';', ':', '!', '?', ')', ']':
297				end--
298			default:
299				return end
300			}
301		}
302		return end
303	}
304	
305	func hasJDBCPassword(candidate string) bool {
306		if !strings.HasPrefix(strings.ToLower(candidate), "jdbc:") {
307			return false
308		}
309		return hasNonPlaceholderPasswordAssignment(candidate)
310	}
311	
312	func hasDatabaseURLSecret(candidate string) bool {
313		u, err := url.Parse(candidate)
314		if err != nil || u.Scheme == "" || u.Host == "" {
315			return false
316		}
317		for key, values := range u.Query() {
318			if !isPasswordQueryKey(key) {
319				continue
320			}
321			for _, value := range values {
322				if hasNonPlaceholderPasswordValue(value) {
323					return true
324				}
325			}
326		}
327		return false
328	}
329	
330	func isPasswordQueryKey(key string) bool {
331		return strings.EqualFold(key, "password") || strings.EqualFold(key, "pwd")
332	}
333	
334	func hasKeywordDSNPassword(candidate string) bool {
335		return keywordHostPattern.MatchString(candidate) &&
336			keywordUserPattern.MatchString(candidate) &&
337			hasNonPlaceholderPasswordAssignment(candidate)
338	}
339	
340	func hasSemicolonConnectionPassword(candidate string) bool {
341		return semicolonServerPattern.MatchString(candidate) &&
342			semicolonUserPattern.MatchString(candidate) &&
343			hasNonPlaceholderPasswordAssignment(candidate)
344	}
345	
346	func detectCredentialValues(s string) []taggedRegion {
347		var regions []taggedRegion
348		for _, loc := range credentialValuePattern.FindAllStringSubmatchIndex(s, -1) {
349			if len(loc) < 6 || loc[4] < 0 || loc[5] < 0 {
350				continue
351			}
352			start, end := unquoteRange(s, loc[4], loc[5])
353			if hasNonPlaceholderPasswordValue(s[start:end]) {
354				regions = append(regions, taggedRegion{region: region{start, end}})
355			}
356		}
357		return regions
358	}
359	
360	func unquoteRange(s string, start, end int) (int, int) {
361		if end-start < 2 {
362			return start, end
363		}
364		first, last := s[start], s[end-1]
365		if (first == '"' && last == '"') || (first == '\'' && last == '\'') {
366			return start + 1, end - 1
367		}
368		return start, end
369	}
370	
371	func hasNonPlaceholderPasswordAssignment(candidate string) bool {
372		for _, loc := range passwordAssignmentRegex.FindAllStringSubmatchIndex(candidate, -1) {
373			if len(loc) >= 4 && loc[2] >= 0 && loc[3] >= 0 {
374				start, end := unquoteRange(candidate, loc[2], loc[3])
375				if hasNonPlaceholderPasswordValue(candidate[start:end]) {
376					return true
377				}
378			}
379		}
380		return false
381	}
382	
383	func hasNonPlaceholderPasswordValue(value string) bool {
384		return value != "" && !isPlaceholderSecretValue(value)
385	}
386	
387	func isPlaceholderSecretValue(value string) bool {
388		trimmed := strings.Trim(strings.TrimSpace(value), `"'`)
389		if trimmed == "" {
390			return true
391		}
392		if isBracketedPlaceholder(trimmed) {
393			return true
394		}
395		normalized := strings.ToLower(trimmed)
396		if strings.HasPrefix(normalized, "${") && strings.HasSuffix(normalized, "}") {
397			return true
398		}
399		if _, ok := placeholderSecretValues[normalized]; ok {
400			return true
401		}
402		return isRepeatedCharPlaceholder(normalized)
403	}
404	
405	// bracketedPlaceholderInteriorRE matches the inside of a "<…>" placeholder
406	// shape: lowercase letters joined by `-` or `_`. Digits, mixed case, and
407	// special chars are rejected so values like `<hunter2>` or `<RealPassword>`
408	// still fall through to redaction.
409	var bracketedPlaceholderInteriorRE = regexp.MustCompile(`^[a-z][a-z_-]*$`)
410	
411	// isBracketedPlaceholder reports whether s is a "<name>" doc placeholder
412	// (e.g. "<password>", "<your-db-password>"). The minimum total length of 5
413	// keeps this from firing on `<a>` / `<ab>`.
414	func isBracketedPlaceholder(s string) bool {
415		if len(s) < 5 || s[0] != '<' || s[len(s)-1] != '>' {
416			return false
417		}
418		return bracketedPlaceholderInteriorRE.MatchString(s[1 : len(s)-1])
419	}
420	
421	// isRepeatedCharPlaceholder reports whether s is a run of a single masking
422	// character commonly used to redact values in docs and screenshots, e.g.
423	// "***", "xxxx", "....", "----". The minimum length of 3 keeps single-char
424	// or 2-char values like `x` or `**` from being treated as masks.
425	func isRepeatedCharPlaceholder(s string) bool {
426		if len(s) < 3 {
427			return false
428		}
429		first := s[0]
430		switch first {
431		case '*', 'x', '.', '-':
432		default:
433			return false
434		}
435		for i := 1; i < len(s); i++ {
436			if s[i] != first {
437				return false
438			}
439		}
440		return true
441	}
442	
443	func isCredentialJSONSecretKey(key string, credentialContext bool) bool {
444		normalized := normalizeCredentialJSONKey(key)
445		if credentialJSONKeyRegex.MatchString(normalized) {
446			return true
447		}
448		return credentialContext && genericPasswordKeyRegex.MatchString(normalized)
449	}
450	
451	func isCredentialJSONObject(obj map[string]any) bool {
452		var hasHost, hasUser bool
453		for key := range obj {
454			switch normalizeCredentialJSONKey(key) {
455			case "host", "hostname", "server", "addr", "address", "datasource", "data_source":
456				hasHost = true
457			case "user", "username", "userid", "user_id", "uid":
458				hasUser = true
459			}
460			if hasHost && hasUser {
461				return true
462			}
463		}
464		return false
465	}
466	
467	func normalizeCredentialJSONKey(key string) string {
468		key = strings.ToLower(strings.TrimSpace(key))
469		key = strings.ReplaceAll(key, "-", "_")
470		key = strings.ReplaceAll(key, " ", "_")
471		// Flattened-config exporters (Spring, dotnet, Hashicorp Vault) emit dotted keys
472		// like "db.password" or "mysql.root.password"; treat them like underscored.
473		key = strings.ReplaceAll(key, ".", "_")
474		return key
475	}
476	
477	// Bytes is a convenience wrapper around String for []byte content.
478	func Bytes(b []byte) []byte {
479		s := string(b)
480		redacted := String(s)
481		if redacted == s {
482			return b
483		}
484		return []byte(redacted)
485	}
486	
487	// JSONLBytes redacts secrets in JSONL-formatted byte content and returns
488	// the result as RedactedBytes, certifying the output has been through redaction.
489	func JSONLBytes(b []byte) (RedactedBytes, error) {
490		s := string(b)
491		redacted, err := JSONLContent(s)
492		if err != nil {
493			return RedactedBytes{}, err
494		}
495		if redacted == s {
496			return RedactedBytes{data: b}, nil
497		}
498		return RedactedBytes{data: []byte(redacted)}, nil
499	}
500	
501	// JSONLContent parses each line as JSON to determine which string values
502	// need redaction, then performs targeted replacements on the raw JSON bytes.
503	// Lines with no secrets are returned unchanged, preserving original formatting.
504	//
505	// For multi-line JSON content (e.g., pretty-printed single JSON objects like
506	// OpenCode export), the function first attempts to parse the entire content as
507	// a single JSON value. This ensures field-aware redaction (which skips ID fields)
508	// is used instead of falling back to entropy-based detection on raw text lines,
509	// which would corrupt high-entropy identifiers.
510	func JSONLContent(content string) (string, error) {
511		// Try parsing the entire content as a single JSON value first.
512		// Uses a streaming decoder to avoid copying the full content into []byte.
513		// After decoding, attempts a second Decode to confirm EOF — if it succeeds,
514		// the content is JSONL (multiple values) and we fall through to line-by-line.
515		trimmed := strings.TrimSpace(content)
516		if len(trimmed) > 0 {
517			dec := json.NewDecoder(strings.NewReader(trimmed))
518			var parsed any
519			if err := dec.Decode(&parsed); err == nil && isSingleJSONValue(dec) {
520				// Content is a single JSON value (object/array) — redact field-aware.
521				result, err := applyJSONReplacements(content, collectJSONLReplacements(parsed))
522				if err != nil {
523					return "", err
524				}
525				return result, nil
526			}
527		}
528	
529		// Fall back to line-by-line JSONL processing.
530		lines := strings.Split(content, "\n")
531		var b strings.Builder
532		for i, line := range lines {
533			if i > 0 {
534				b.WriteByte('\n')
535			}
536			lineTrimmed := strings.TrimSpace(line)
537			if lineTrimmed == "" {
538				b.WriteString(line)
539				continue
540			}
541			var parsed any
542			if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
543				b.WriteString(String(line))
544				continue
545			}
546			result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed))
547			if err != nil {
548				return "", err
549			}
550			b.WriteString(result)
551		}
552		return b.String(), nil
553	}
554	
555	// applyJSONReplacements applies collected (original, redacted) string pairs
556	// to the raw JSON text, replacing JSON-encoded originals with their redacted forms.
557	// Returns s unchanged if repls is empty.
558	func applyJSONReplacements(s string, repls []jsonReplacement) (string, error) {
559		if len(repls) == 0 {
560			return s, nil
561		}
562		for _, r := range repls {
563			origJSON, err := jsonEncodeString(r.original)
564			if err != nil {
565				return "", err
566			}
567			replJSON, err := jsonEncodeString(r.redacted)
568			if err != nil {
569				return "", err
570			}
571			if r.key == "" {
572				s = strings.ReplaceAll(s, origJSON, replJSON)
573				continue
574			}
575			keyJSON, err := jsonEncodeString(r.key)
576			if err != nil {
577				return "", err
578			}
579			s = replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON)
580		}
581		return s, nil
582	}
583	
584	// replaceKeyedJSONValue replaces every occurrence of origJSON that follows
585	// keyJSON + optional whitespace + ':' + optional whitespace. Restricts
586	// substitution to value positions so a key's own redacted text is not
587	// rewritten when it collides with another field's value.
588	func replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON string) string {
589		if !strings.Contains(s, keyJSON) {
590			return s
591		}
592		var b strings.Builder
593		b.Grow(len(s))
594		i := 0
595		for i < len(s) {
596			j := strings.Index(s[i:], keyJSON)
597			if j < 0 {
598				b.WriteString(s[i:])
599				break
600			}
601			keyEnd := i + j + len(keyJSON)
602			b.WriteString(s[i : i+j])
603			b.WriteString(keyJSON)
604			p := keyEnd
605			for p < len(s) && isJSONWhitespace(s[p]) {
606				p++
607			}
608			if p >= len(s) || s[p] != ':' {
609				i = keyEnd
610				continue
611			}
612			p++
613			for p < len(s) && isJSONWhitespace(s[p]) {
614				p++
615			}
616			if p+len(origJSON) <= len(s) && s[p:p+len(origJSON)] == origJSON {
617				b.WriteString(s[keyEnd:p])
618				b.WriteString(replJSON)
619				i = p + len(origJSON)
620				continue
621			}
622			i = keyEnd
623		}
624		return b.String()
625	}
626	
627	func isJSONWhitespace(c byte) bool {
628		return c == ' ' || c == '\t' || c == '\n' || c == '\r'
629	}
630	
631	// isSingleJSONValue returns true if the decoder has reached EOF (no more
632	// top-level values). This distinguishes a single JSON value (e.g., pretty-printed
633	// object) from JSONL (multiple concatenated values). We attempt a second Decode
634	// and require io.EOF rather than relying on dec.More(), which is documented for
635	// use inside arrays/objects and not for top-level value boundaries.
636	func isSingleJSONValue(dec *json.Decoder) bool {
637		var discard json.RawMessage
638		return dec.Decode(&discard) == io.EOF
639	}
640	
641	// collectJSONLReplacements walks a parsed JSON value and collects unique string
642	// replacements for values that need redaction.
643	func collectJSONLReplacements(v any) []jsonReplacement {
644		seen := make(map[string]bool)
645		var repls []jsonReplacement
646		var walk func(key string, credentialContext bool, v any)
647		walk = func(key string, credentialContext bool, v any) {
648			switch val := v.(type) {
649			case map[string]any:
650				if shouldSkipJSONLObject(val) {
651					return
652				}
653				childCredentialContext := credentialContext || isCredentialJSONObject(val)
654				for k, child := range val {
655					if shouldSkipJSONLField(k) {
656						continue
657					}
658					walk(k, childCredentialContext, child)
659				}
660			case []any:
661				for _, child := range val {
662					walk("", credentialContext, child)
663				}
664			case string:
665				redacted := String(val)
666				if redacted == val && isCredentialJSONSecretKey(key, credentialContext) && hasNonPlaceholderPasswordValue(val) {
667					redacted = RedactedPlaceholder
668				}
669				if redacted != val {
670					seenKey := key + "\x00" + val
671					if !seen[seenKey] {
672						seen[seenKey] = true
673						repls = append(repls, jsonReplacement{key: key, original: val, redacted: redacted})
674					}
675				}
676			}
677		}
678		walk("", false, v)
679		return repls
680	}
681	
682	// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
683	// Skips "signature" (exact), ID fields (ending in "id"/"ids"), and common path/directory fields.
684	func shouldSkipJSONLField(key string) bool {
685		if key == "signature" {
686			return true
687		}
688		lower := strings.ToLower(key)
689	
690		// Skip ID fields
691		if strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids") {
692			return true
693		}
694	
695		// Skip common path and directory fields from agent transcripts.
696		// These appear frequently in tool calls and are structural, not secrets.
697		switch lower {
698		case "filepath", "file_path", "cwd", "root", "directory", "dir", "path":
699			return true
700		}
701	
702		return false
703	}
704	
705	// shouldSkipJSONLObject returns true if the object has "type":"image" or "type":"image_url".
706	func shouldSkipJSONLObject(obj map[string]any) bool {
707		t, ok := obj["type"].(string)
708		return ok && (strings.HasPrefix(t, "image") || t == "base64")
709	}
710	
711	func shannonEntropy(s string) float64 {
712		if len(s) == 0 {
713			return 0
714		}
715		freq := make(map[byte]int)
716		for i := range len(s) {
717			freq[s[i]]++
718		}
719		length := float64(len(s))
720		var entropy float64
721		for _, count := range freq {
722			p := float64(count) / length
723			entropy -= p * math.Log2(p)
724		}
725		return entropy
726	}
727	
728	// jsonEncodeString returns the JSON encoding of s without HTML escaping.
729	func jsonEncodeString(s string) (string, error) {
730		var buf bytes.Buffer
731		enc := json.NewEncoder(&buf)
732		enc.SetEscapeHTML(false)
733		if err := enc.Encode(s); err != nil {
734			return "", fmt.Errorf("json encode string: %w", err)
735		}
736		return strings.TrimSuffix(buf.String(), "\n"), nil
737	}
