#!/bin/bash
# Stub opf for adapter contract tests. Reads stdin (ignored), writes a
# canned OPF-shaped JSON response that exercises one private_person span.
# Exit status, sleep duration, and output are controlled via env vars so
# tests can simulate every failure mode without needing real OPF installed.

set -u

if [[ -n "${FAKE_OPF_SLEEP_SECONDS:-}" ]]; then
  sleep "${FAKE_OPF_SLEEP_SECONDS}"
fi

# Drain stdin so the parent doesn't block on a partial write.
cat > /dev/null || true

if [[ -n "${FAKE_OPF_STDERR:-}" ]]; then
  echo "${FAKE_OPF_STDERR}" >&2
fi

if [[ -n "${FAKE_OPF_OUTPUT:-}" ]]; then
  printf '%s' "${FAKE_OPF_OUTPUT}"
else
  cat <<'EOF'
{
  "schema_version": 1,
  "summary": {"output_mode": "typed", "span_count": 1, "by_label": {"private_person": 1}, "decoded_mismatch": false},
  "text": "Alice is here.",
  "detected_spans": [
