```go
package opf_runtime

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"os/exec"
	"strings"
	"time"
)

// shellOut runs the user-installed `opf` binary per call. Cold-start every
// invocation is intentional for v1 — see the spec's runtime decision section.
// Daemon mode (a future implementation of Runtime) reuses this same wire
// format so callers do not change.
type shellOut struct {
	command        string
	timeoutSeconds int
}

type opfOutput struct {
	DetectedSpans []struct {
		Label string `json:"label"`
		Start int    `json:"start"`
		End   int    `json:"end"`
		Text  string `json:"text"`
	} `json:"detected_spans"`
}

func (s *shellOut) Redact(ctx context.Context, text string, categories []string) ([]Span, error) {
	if len(categories) == 0 {
		return nil, nil // nothing to do
	}
	timeout := time.Duration(s.timeoutSeconds) * time.Second
	callCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	args := []string{
		"--device", "cpu",
		"--output-mode", "typed",
		// Tell opf to read from stdin so we can stream text without a temp file.
		// Categories are passed via --labels; the wire flag name matches what
		// upstream `opf redact --help` documents.
		"--labels", strings.Join(categories, ","),
	}

	cmd := exec.CommandContext(callCtx, s.command, args...)
	cmd.Stdin = strings.NewReader(text)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		if callCtx.Err() == context.DeadlineExceeded {
			return nil, fmt.Errorf("opf timeout after %s: %w", timeout, callCtx.Err())
		}
		errMsg := strings.TrimSpace(stderr.String())
		if errMsg == "" {
			errMsg = err.Error()
		}
		return nil, fmt.Errorf("opf exited with error: %s", errMsg)
	}

	var parsed opfOutput
	if err := json.Unmarshal(stdout.Bytes(), &parsed); err != nil {
		return nil, fmt.Errorf("opf output not parseable as JSON: %w (stdout: %q)", err, stdout.String())
	}

	out := make([]Span, 0, len(parsed.DetectedSpans))
	for _, p := range parsed.DetectedSpans {
		out = append(out, Span{Start: p.Start, End: p.End, Label: p.Label})
	}
	return out, nil
}

func (s *shellOut) Close() error { return nil }
```

NOTE on `--labels` flag: verify the actual flag name against `opf redact --help` during implementation. If the flag does not exist with that exact name, swap to the correct one (likely `--categories` or similar). The benchmark step in Chunk 4 also requires running `opf` locally, which is the right point to verify this against the real binary.

